:root{
  --bg:#f4f8f8;
  --bg-2:#eef4f4;
  --surface:#ffffff;
  --line:#e2ebeb;
  --line-soft:#edf3f3;
  --text:#0e2b29;
  --text-2:#476663;
  --text-3:#8aa3a1;
  --text-4:#a9bebd;
  --accent:#0d9488;
  --accent-dark:#0b7f74;
  --accent-deep:#075e56;
  --accent-soft:#e4f4f1;
  --accent-soft2:#f1fafa;
  --cyan:#0e93b5;
  --cyan-soft:#e5f3f8;
  --danger:#d13b38;
  --danger-soft:#fdeceb;
  --danger-line:#f4c6c5;
  --warn:#a86206;
  --warn-soft:#fdf4e6;
  --warn-line:#f0dcb2;
  --radius:14px;
  --radius-sm:10px;
  --radius-xs:8px;
  --sh-1:0 1px 2px rgba(10,50,46,.05);
  --sh-2:0 1px 2px rgba(10,50,46,.04), 0 4px 14px rgba(10,50,46,.045);
  --sh-3:0 2px 4px rgba(10,50,46,.05), 0 12px 32px rgba(10,50,46,.07);
  --sh-4:0 20px 50px rgba(8,42,39,.16);
  --nav-w:248px;
  --serif:ui-serif,"Songti SC","Georgia","Times New Roman",serif;
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0;padding:0}
html{-webkit-text-size-adjust:100%}
body{overflow-x:hidden}

/* 全局 SVG 兜底尺寸 —— 防止任何未显式约束的图标撑满容器 */
svg{width:16px;height:16px;flex:0 0 auto;display:inline-block;vertical-align:middle}

body{
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;
  background:var(--bg); color:var(--text);
  font-size:14px; line-height:1.6;
  -webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;
  font-variant-numeric:tabular-nums;
}
button,input,select,textarea{font-family:inherit;font-size:14px;color:inherit}
button{cursor:pointer;border:none;background:none;padding:0}
::-webkit-scrollbar{width:11px;height:11px}
::-webkit-scrollbar-thumb{background:#cfdedd;border-radius:9px;border:3.5px solid var(--bg);background-clip:padding-box}
::-webkit-scrollbar-thumb:hover{background:#b9cfcd;background-clip:padding-box}
::-webkit-scrollbar-track{background:transparent}

/* ================= Layout ================= */
.app{display:flex;min-height:100vh}
.nav{
  width:var(--nav-w);flex:0 0 var(--nav-w);
  background:linear-gradient(180deg,#fff 0%,#fbfdfd 60%,#f7fbfb 100%);
  border-right:1px solid var(--line);
  padding:24px 16px 20px;position:sticky;top:0;height:100vh;
  display:flex;flex-direction:column;gap:3px;
}
.brand{display:flex;align-items:center;gap:11px;padding:0 6px 20px;margin-bottom:2px;border-bottom:1px solid var(--line-soft)}
.brand-mark{
  width:36px;height:36px;border-radius:11px;flex:0 0 36px;
  background:linear-gradient(145deg,#12a89a 0%,var(--accent) 45%,#0b7fa0 100%);
  display:flex;align-items:center;justify-content:center;color:#fff;
  box-shadow:0 3px 10px rgba(13,148,136,.32), inset 0 1px 0 rgba(255,255,255,.28);
}
.brand-mark svg{width:19px;height:19px}
.brand-t{font-weight:660;font-size:15.5px;letter-spacing:.1px;line-height:1.25}
.brand-s{font-size:11.5px;color:var(--text-3);margin-top:1px;letter-spacing:.2px}
.nav-label{font-size:10.5px;color:var(--text-4);padding:16px 10px 7px;letter-spacing:1.1px;font-weight:700;text-transform:uppercase}

/* 语言切换 */
.lang-btn{
  margin-left:auto;flex:0 0 auto;align-self:flex-start;
  padding:3.5px 9px;border-radius:20px;border:1px solid var(--line);
  background:var(--surface);color:var(--text-2);
  font-size:11px;font-weight:700;letter-spacing:.3px;transition:.15s;box-shadow:var(--sh-1);
}
.lang-btn:hover{border-color:var(--accent);color:var(--accent-deep);background:var(--accent-soft2)}
.nav-item{
  display:flex;align-items:center;gap:11px;width:100%;position:relative;
  padding:10px 11px;border-radius:var(--radius-sm);
  color:var(--text-2);font-weight:520;text-align:left;font-size:13.5px;
  transition:background .16s ease,color .16s ease;
}
.nav-item:hover{background:var(--accent-soft2);color:var(--text)}
.nav-item.on{background:var(--accent-soft);color:var(--accent-deep);font-weight:650}
.nav-item.on::before{
  content:"";position:absolute;left:-16px;top:50%;transform:translateY(-50%);
  width:3px;height:19px;border-radius:0 3px 3px 0;background:var(--accent);
}
.nav-item.on svg{color:var(--accent)}
.nav-item svg{width:17px;height:17px;color:var(--text-3);transition:color .16s}
.nav-item:hover svg{color:var(--accent-dark)}
.nav-count{
  margin-left:auto;font-size:11px;font-weight:700;min-width:21px;text-align:center;
  padding:1.5px 6px;border-radius:20px;background:var(--bg-2);color:var(--text-2);letter-spacing:.2px
}
.nav-item.on .nav-count{background:#fff;color:var(--accent-deep)}
.nav-count.hot{background:var(--danger);color:#fff;box-shadow:0 1px 4px rgba(209,59,56,.3)}
.nav-count.zero{display:none}
.nav-foot{margin-top:auto;padding:14px 11px 0;border-top:1px solid var(--line-soft);font-size:11px;color:var(--text-4);line-height:1.75}
.nav-foot b{display:block;color:var(--text-3);font-weight:600}

.main{flex:1;min-width:0;padding:28px 36px 80px;max-width:1200px}

/* ================= Hero ================= */
.hero{
  position:relative;border-radius:var(--radius);overflow:hidden;margin-bottom:20px;
  box-shadow:var(--sh-2);border:1px solid var(--line);background:#f7faf9;
  min-height:158px;display:flex;align-items:center;
}
.hero-img{position:absolute;inset:0;background-size:cover;background-position:center 62%;opacity:.96}
.hero-ov{position:absolute;inset:0;background:
  linear-gradient(100deg,rgba(255,255,255,.97) 0%,rgba(255,255,255,.93) 34%,rgba(255,255,255,.6) 56%,rgba(255,255,255,.12) 78%,rgba(255,255,255,0) 100%),
  linear-gradient(180deg,rgba(13,148,136,.05),rgba(14,147,181,.05));}
.hero-c{position:relative;padding:26px 30px;max-width:640px;min-width:0}
.hero-eyebrow{display:flex;align-items:center;gap:7px;font-size:11.5px;font-weight:700;letter-spacing:1.2px;color:var(--accent-dark);text-transform:uppercase;margin-bottom:9px;flex-wrap:wrap}
.hero-eyebrow svg{width:14px;height:14px}
.hero h1{margin:0;font-family:var(--serif);font-size:27px;font-weight:600;letter-spacing:-.3px;line-height:1.3;color:#0b2a28;word-break:break-word}
.hero p{margin:8px 0 0;font-size:13.5px;color:var(--text-2);line-height:1.7;max-width:520px;word-break:break-word}
.hero p b{color:var(--accent-deep);font-weight:660}
.hero p .rd{color:var(--danger);font-weight:660}

/* ================= Topbar ================= */
.topbar{display:flex;align-items:flex-end;gap:16px;flex-wrap:wrap;margin-bottom:20px}
.topbar h1{margin:0;font-size:22px;font-weight:660;letter-spacing:-.35px;line-height:1.3}
.topbar .sub{font-size:12.5px;color:var(--text-3);margin-top:4px;line-height:1.6}
.topbar-act{margin-left:auto;display:flex;gap:8px;flex-wrap:wrap}

/* ================= Buttons ================= */
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:6px;
  padding:8.5px 15px;border-radius:var(--radius-sm);font-weight:600;font-size:13px;
  background:var(--surface);border:1px solid var(--line);color:var(--text-2);
  transition:border-color .15s,background .15s,color .15s,box-shadow .15s,transform .1s;
  white-space:nowrap;box-shadow:var(--sh-1);letter-spacing:.1px;
}
.btn:hover{border-color:#c3d8d6;color:var(--text);box-shadow:var(--sh-2)}
.btn:active{transform:translateY(.5px)}
.btn svg{width:15px;height:15px}
.btn-primary{
  background:linear-gradient(180deg,#12a094,var(--accent-dark));
  border-color:var(--accent-dark);color:#fff;
  box-shadow:0 1px 2px rgba(11,127,116,.2),0 4px 12px rgba(11,127,116,.22),inset 0 1px 0 rgba(255,255,255,.16);
}
.btn-primary:hover{background:linear-gradient(180deg,var(--accent-dark),var(--accent-deep));border-color:var(--accent-deep);color:#fff;box-shadow:0 2px 4px rgba(11,127,116,.24),0 7px 18px rgba(11,127,116,.28),inset 0 1px 0 rgba(255,255,255,.16)}
.btn-danger{color:var(--danger);border-color:var(--danger-line);background:var(--surface)}
.btn-danger:hover{background:var(--danger-soft);color:var(--danger);border-color:#eaa9a7}
.btn-sm{padding:6px 11px;font-size:12px;border-radius:var(--radius-xs)}
.btn-sm svg{width:13.5px;height:13.5px}

/* ================= Card ================= */
.card{
  background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);
  box-shadow:var(--sh-2);margin-bottom:18px;overflow:hidden;
  transition:box-shadow .22s ease;
}
.card:hover{box-shadow:var(--sh-3)}
.card-h{
  display:flex;align-items:center;gap:10px;padding:15px 20px;flex-wrap:wrap;
  border-bottom:1px solid var(--line-soft);
  background:linear-gradient(180deg,#fdfefe,#fafcfc);
}
.card-h > svg{width:17px;height:17px;color:var(--accent);flex:0 0 17px}
.card-h h2{margin:0;font-size:14.5px;font-weight:660;letter-spacing:-.1px}
.card-h .hint{font-size:11.5px;color:var(--text-4);font-weight:500}
.card-h .sp{margin-left:auto;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.card-b{padding:18px 20px}
.card-b.tight{padding:5px 20px 14px}

/* ================= Focus banner ================= */
.focus{
  border:1px solid var(--danger-line);border-radius:var(--radius);margin-bottom:18px;
  box-shadow:0 1px 2px rgba(180,50,46,.05),0 6px 20px rgba(180,50,46,.08);overflow:hidden;
  background:linear-gradient(180deg,#fffbfb,#fff);
}
.focus.clear{
  border-color:#cfe8e4;background:linear-gradient(180deg,var(--accent-soft2),#fff);
  box-shadow:0 1px 2px rgba(10,90,82,.04),0 6px 20px rgba(10,90,82,.06);
}
.focus-h{
  display:flex;align-items:center;gap:10px;padding:15px 20px;
  border-bottom:1px solid var(--danger-line);
  background:linear-gradient(180deg,rgba(209,59,56,.05),transparent);
}
.focus.clear .focus-h{border-color:#dcece9;background:linear-gradient(180deg,rgba(13,148,136,.05),transparent)}
.focus-h h2{margin:0;font-size:15px;font-weight:700;color:var(--danger);letter-spacing:-.1px}
.focus.clear .focus-h h2{color:var(--accent-deep)}
.focus-h > svg{width:18px;height:18px;color:var(--danger);flex:0 0 18px}
.focus.clear .focus-h > svg{color:var(--accent)}
.focus-h .sp{margin-left:auto;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.focus-b{padding:4px 20px 14px}
.frow{display:flex;align-items:flex-start;gap:11px;padding:11px 0;border-bottom:1px solid var(--line-soft)}
.frow:last-child{border-bottom:none}
.frow .ft{flex:1;min-width:0}
.frow .ft b{font-weight:600;display:block;word-break:break-word;font-size:13.8px;letter-spacing:-.05px}
.frow .ft span{font-size:12px;color:var(--text-2);display:block;margin-top:3px;word-break:break-word;line-height:1.6}
.frow .ft span b,.frow .ft span strong{display:inline}
.frow .fa{display:flex;gap:6px;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end;align-items:center}
.dot{width:6px;height:6px;border-radius:50%;background:var(--danger);margin-top:8px;flex:0 0 6px;box-shadow:0 0 0 3px rgba(209,59,56,.13)}
.allclear{display:flex;align-items:center;gap:9px;padding:11px 0;color:var(--text-2);font-size:13px}
.allclear svg{width:17px;height:17px;color:var(--accent)}

/* 非焦点页的紧凑提醒条 */
.mini-alert{
  display:flex;align-items:center;gap:10px;padding:11px 16px;margin-bottom:18px;
  border:1px solid var(--danger-line);border-radius:var(--radius-sm);
  background:linear-gradient(180deg,#fff9f9,#fff);box-shadow:var(--sh-1);
}
.mini-alert > svg{width:16px;height:16px;color:var(--danger);flex:0 0 16px}
.mini-alert .mt{flex:1;min-width:0;font-size:13px;color:#7a2c2a}
.mini-alert .mt b{color:var(--danger);font-weight:700}

/* ================= Pills ================= */
.pill{
  display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:650;
  padding:2.5px 9px;border-radius:20px;background:var(--bg-2);color:var(--text-2);
  white-space:nowrap;letter-spacing:.1px;line-height:1.6;
}
.pill.red{background:var(--danger-soft);color:var(--danger);box-shadow:inset 0 0 0 1px rgba(209,59,56,.13)}
.pill.teal{background:var(--accent-soft);color:var(--accent-deep);box-shadow:inset 0 0 0 1px rgba(13,148,136,.13)}
.pill.cyan{background:var(--cyan-soft);color:#0a6f8c;box-shadow:inset 0 0 0 1px rgba(14,147,181,.13)}
.pill.warn{background:var(--warn-soft);color:var(--warn);box-shadow:inset 0 0 0 1px rgba(168,98,6,.13)}
.pill.gray{background:#f0f5f5;color:var(--text-3)}
.p1{background:#fdeceb;color:#bd302d;box-shadow:inset 0 0 0 1px rgba(189,48,45,.14)}
.p2{background:var(--warn-soft);color:#96580a;box-shadow:inset 0 0 0 1px rgba(150,88,10,.14)}
.p3{background:var(--cyan-soft);color:#0a6f8c;box-shadow:inset 0 0 0 1px rgba(10,111,140,.13)}
.p4{background:#f0f5f5;color:#6b8483}

/* ================= Forms ================= */
.form{display:flex;gap:11px;flex-wrap:wrap;align-items:flex-end}
.f{display:flex;flex-direction:column;gap:6px;min-width:0}
.f.grow{flex:1 1 220px}
.f label{font-size:11px;font-weight:700;color:var(--text-3);letter-spacing:.5px;text-transform:uppercase}
input[type=text],input[type=date],select,textarea{
  width:100%;padding:9.5px 12px;border:1px solid var(--line);border-radius:var(--radius-sm);
  background:#fcfefe;outline:none;transition:border-color .15s,box-shadow .15s,background .15s;
}
input[type=text]:hover,input[type=date]:hover,select:hover,textarea:hover{border-color:#cfdedd}
textarea{resize:vertical;min-height:78px;line-height:1.68}
input:focus,select:focus,textarea:focus{border-color:var(--accent);background:#fff;box-shadow:0 0 0 3.5px rgba(13,148,136,.1)}
input::placeholder,textarea::placeholder{color:var(--text-4)}
select{appearance:none;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='16' height='16' viewBox='0 0 24 24' fill='none' stroke='%238aa3a1' stroke-width='2.4' stroke-linecap='round'><path d='M6 9l6 6 6-6'/></svg>");background-repeat:no-repeat;background-position:right 10px center;padding-right:32px}

/* ================= Task list ================= */
.seg{display:inline-flex;background:var(--bg-2);border-radius:var(--radius-sm);padding:3px;gap:2px}
.seg button{padding:5.5px 13px;border-radius:7px;font-size:12.5px;font-weight:600;color:var(--text-2);transition:.15s}
.seg button:hover{color:var(--text)}
.seg button.on{background:var(--surface);color:var(--accent-deep);box-shadow:0 1px 3px rgba(10,50,46,.1)}
.list{display:flex;flex-direction:column}
.item{
  display:flex;gap:12px;padding:13px 0;border-bottom:1px solid var(--line-soft);
  align-items:flex-start;position:relative;transition:background .15s;
}
.item:last-child{border-bottom:none}
.item::before{content:"";position:absolute;left:-20px;top:11px;bottom:11px;width:2.5px;border-radius:0 3px 3px 0;background:transparent;transition:background .15s}
.item.pr1::before{background:#d9403c}
.item.pr2::before{background:#dc8a12}
.item.pr3::before{background:var(--cyan)}
.item.pr4::before{background:#c2d3d2}
.item.done::before{background:#dbe7e6}
.item.od{background:linear-gradient(90deg,rgba(209,59,56,.075),rgba(209,59,56,.025) 55%,transparent 82%);margin:0 -20px;padding:13px 20px}
.item.od::before{left:0}
.item.od .it-title{color:#bd302d}
.item.done .it-title{text-decoration:line-through;text-decoration-color:var(--text-4);color:var(--text-3)}
.chk{
  width:20px;height:20px;flex:0 0 20px;border:1.8px solid #c2d6d5;border-radius:6px;margin-top:2px;
  display:flex;align-items:center;justify-content:center;background:#fff;transition:.16s;
}
.chk:hover{border-color:var(--accent);background:var(--accent-soft2);transform:scale(1.06)}
.chk.on{background:linear-gradient(180deg,#12a096,var(--accent-dark));border-color:var(--accent-dark);box-shadow:0 1px 4px rgba(13,148,136,.3)}
.chk svg{width:12.5px;height:12.5px;color:#fff;opacity:0;stroke-width:3.6}
.chk.on svg{opacity:1}
.it-main{flex:1;min-width:0}
.it-title{font-weight:545;word-break:break-word;font-size:13.9px;letter-spacing:-.05px;line-height:1.55}
.it-meta{display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-top:5px}
.it-act{display:flex;gap:3px;flex-shrink:0;align-items:center}
.ico-btn{width:31px;height:31px;border-radius:var(--radius-xs);display:flex;align-items:center;justify-content:center;color:var(--text-4);transition:.15s}
.ico-btn:hover{background:var(--bg-2);color:var(--text-2)}
.ico-btn.red:hover{background:var(--danger-soft);color:var(--danger)}
.ico-btn svg{width:15px;height:15px}

/* ================= 日期分组（即将到来） ================= */
.dgroup{margin-bottom:6px}
.dgroup:last-child{margin-bottom:0}
.dgroup-h{
  display:flex;align-items:center;gap:9px;padding:12px 0 7px;
  position:sticky;top:0;background:linear-gradient(180deg,#fff 72%,rgba(255,255,255,0));z-index:2;
}
.dg-d{font-size:12.5px;font-weight:700;color:var(--accent-deep);letter-spacing:.1px}
.dg-x{font-size:11.5px;color:var(--text-4)}
.dg-n{margin-left:auto;font-size:11px;font-weight:650;color:var(--text-3);background:var(--bg-2);padding:1.5px 8px;border-radius:20px}
.dgroup .list{border-left:2px solid var(--line-soft);padding-left:13px;margin-left:2px}
.dgroup .item::before{display:none}

/* ================= 子筛选栏（按项目） ================= */
.subbar{
  display:flex;align-items:center;gap:7px;flex-wrap:wrap;
  padding:11px 20px;border-bottom:1px solid var(--line-soft);background:#fcfdfd;
}
.sb-l{font-size:11px;font-weight:700;color:var(--text-4);letter-spacing:.5px;text-transform:uppercase;margin-right:2px}

/* 任务上的项目标签 */
.pill.proj-link{
  background:var(--accent-soft);color:var(--accent-deep);cursor:pointer;
  box-shadow:inset 0 0 0 1px rgba(13,148,136,.16);transition:.15s;border:none;font-family:inherit;
}
.pill.proj-link:hover{background:var(--accent);color:#fff;box-shadow:0 1px 5px rgba(13,148,136,.3)}
.pill.proj-link svg{width:11px;height:11px}

/* ================= 项目卡内的关联待办 ================= */
.ptasks{margin-top:11px;padding-top:11px;border-top:1px solid var(--line-soft)}
.pt-h{display:flex;align-items:center;gap:8px;margin-bottom:9px;flex-wrap:wrap}
.pt-t{font-size:11px;font-weight:700;color:var(--text-4);letter-spacing:.5px;text-transform:uppercase}
.pt-c{font-size:11.5px;font-weight:650;color:var(--text-2)}
.pt-c .rd{color:var(--danger)}
.pt-h .btn{margin-left:auto}
.pt-bar{height:6px;background:var(--bg-2);border-radius:20px;overflow:hidden;margin-bottom:10px;box-shadow:inset 0 1px 2px rgba(10,50,46,.05)}
.pt-fill{display:block;height:100%;border-radius:20px;background:linear-gradient(90deg,var(--accent),var(--cyan));transition:width .5s cubic-bezier(.4,0,.2,1)}
.pt-fill.full{background:linear-gradient(90deg,var(--accent),#3fbfa8)}
.pt-list{display:flex;flex-direction:column;gap:1px}
.pt-i{display:flex;align-items:center;gap:8px;padding:5px 0;font-size:12.5px}
.pt-chk{
  width:16px;height:16px;flex:0 0 16px;border:1.6px solid #c8dad9;border-radius:5px;
  display:flex;align-items:center;justify-content:center;background:#fff;transition:.15s;
}
.pt-chk:hover{border-color:var(--accent);background:var(--accent-soft)}
.pt-chk svg{width:10px;height:10px;color:var(--accent);opacity:0;stroke-width:3.6}
.pt-chk:hover svg{opacity:.75}
.pt-n{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#20403e}
.pt-d{font-size:11px;color:var(--text-4);flex-shrink:0;font-weight:550}
.pt-d.od{color:var(--danger);font-weight:700}
.pt-more{
  margin-top:5px;font-size:11.5px;font-weight:650;color:var(--accent-dark);
  text-align:left;padding:3px 0;transition:.15s;
}
.pt-more:hover{color:var(--accent-deep);text-decoration:underline}
.pt-none{font-size:12px;color:var(--text-4);line-height:1.6}
.pt-done{display:flex;align-items:center;gap:7px;font-size:12px;color:var(--accent-dark);font-weight:550}
.pt-done svg{width:14px;height:14px;color:var(--accent)}

/* ================= Notes ================= */
.tagbar{display:flex;gap:7px;flex-wrap:wrap}
.tag-chip{
  padding:4.5px 12px;border-radius:20px;border:1px solid var(--line);font-size:12px;
  font-weight:600;color:var(--text-2);background:var(--surface);transition:.15s;box-shadow:var(--sh-1);
}
.tag-chip:hover{border-color:#bfd6d4;color:var(--text)}
.tag-chip.on{background:linear-gradient(180deg,#12a096,var(--accent-dark));border-color:var(--accent-dark);color:#fff;box-shadow:0 2px 7px rgba(13,148,136,.28)}
.notes{display:grid;grid-template-columns:repeat(auto-fill,minmax(258px,1fr));gap:13px}
.note{
  border:1px solid var(--line);border-radius:var(--radius-sm);padding:15px 16px;position:relative;
  background:linear-gradient(165deg,#f6fcfb 0%,#fff 55%);transition:box-shadow .2s,border-color .2s,transform .2s;
  box-shadow:var(--sh-1);
}
.note::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;border-radius:var(--radius-sm) 0 0 var(--radius-sm);background:linear-gradient(180deg,var(--accent),var(--cyan));opacity:.8}
.note:hover{box-shadow:var(--sh-3);border-color:#cfe3e1;transform:translateY(-1.5px)}
.note:hover::before{opacity:1}
.note p{margin:0 0 11px;white-space:pre-wrap;word-break:break-word;font-size:13.4px;line-height:1.68;padding-right:26px;color:#173432}
.note .nf{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.note .nf time{font-size:11px;color:var(--text-4);margin-left:auto;font-weight:500}
.note .del{position:absolute;top:8px;right:8px;opacity:0;transition:.15s}
.note:hover .del{opacity:1}

/* ================= Projects ================= */
.projs{display:grid;grid-template-columns:repeat(auto-fill,minmax(310px,1fr));gap:13px}
.proj{
  border:1px solid var(--line);border-radius:var(--radius-sm);padding:16px;background:var(--surface);
  box-shadow:var(--sh-1);transition:box-shadow .2s,transform .2s,border-color .2s;position:relative;overflow:hidden;
}
.proj::after{content:"";position:absolute;left:0;right:0;top:0;height:2.5px;background:linear-gradient(90deg,var(--accent),var(--cyan))}
.proj:hover{box-shadow:var(--sh-3);transform:translateY(-1.5px)}
.proj.blocked{border-color:var(--danger-line);background:linear-gradient(180deg,#fffbfb,#fff)}
.proj.blocked::after{background:linear-gradient(90deg,var(--danger),#e7716e)}
.proj.done{background:linear-gradient(180deg,#f7fbfa,#fff)}
.proj.done::after{background:linear-gradient(90deg,#c2d3d2,#d8e5e4)}
.proj-h{display:flex;align-items:center;gap:9px;margin-bottom:11px;padding-bottom:11px;border-bottom:1px solid var(--line-soft)}
.proj-h b{font-size:14.5px;font-weight:660;word-break:break-word;letter-spacing:-.15px}
.proj-h .sp{margin-left:auto;display:flex;gap:2px;align-items:center;flex-shrink:0}
.kv{display:flex;gap:10px;padding:5.5px 0;font-size:13px;align-items:flex-start}
.kv .k{flex:0 0 50px;color:var(--text-4);font-size:11px;font-weight:700;padding-top:2.5px;letter-spacing:.4px;text-transform:uppercase}
.kv .v{flex:1;min-width:0;word-break:break-word;white-space:pre-wrap;line-height:1.62;color:#1c3b39}
.kv .v.em{color:var(--danger);font-weight:560}
.kv .v.na{color:var(--text-4)}

/* ================= Review ================= */
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(142px,1fr));gap:13px}
.stat{
  border:1px solid var(--line);border-radius:var(--radius-sm);padding:15px 16px;
  background:linear-gradient(165deg,#f4fbfa,#fff 70%);box-shadow:var(--sh-1);
  transition:box-shadow .2s,transform .2s;
}
.stat:hover{box-shadow:var(--sh-2);transform:translateY(-1px)}
.stat .n{font-family:var(--serif);font-size:31px;font-weight:600;letter-spacing:-.8px;line-height:1.1;color:var(--accent-deep)}
.stat .l{font-size:11.5px;color:var(--text-3);margin-top:5px;font-weight:600;letter-spacing:.3px}
.stat.red{background:linear-gradient(165deg,#fef7f7,#fff 70%);border-color:var(--danger-line)}
.stat.red .n{color:var(--danger)}
.bars{display:flex;flex-direction:column;gap:13px}
.bar-row{display:flex;align-items:center;gap:12px}
.bar-row .bl{flex:0 0 108px;font-size:12.5px;color:var(--text-2);font-weight:570}
.bar-track{flex:1;display:block;height:9px;background:var(--bg-2);border-radius:20px;overflow:hidden;box-shadow:inset 0 1px 2px rgba(10,50,46,.05)}
.bar-fill{display:block;height:100%;min-width:3px;border-radius:20px;transition:width .5s cubic-bezier(.4,0,.2,1);box-shadow:inset 0 1px 0 rgba(255,255,255,.25)}
.bar-fill.z{min-width:0}
.bar-row .bv{flex:0 0 48px;text-align:right;font-size:12.5px;font-weight:700;color:var(--text-2)}
.blk{padding:10px 0;border-bottom:1px solid var(--line-soft);font-size:13px;line-height:1.65}
.blk:last-child{border-bottom:none}
.blk b{font-weight:650}
.blk span{color:var(--danger)}

/* ================= Empty ================= */
.empty{text-align:center;padding:34px 16px;color:var(--text-4);font-size:13px}
.empty svg{width:28px;height:28px;margin-bottom:10px;color:#c9dbda;stroke-width:1.6}

/* ================= Backup ================= */
.bk-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(228px,1fr));gap:13px}
.bk{border:1px solid var(--line);border-radius:var(--radius-sm);padding:17px;background:linear-gradient(165deg,#fbfefe,#fff);box-shadow:var(--sh-1)}
.bk h3{margin:0 0 6px;font-size:13.5px;font-weight:660;display:flex;align-items:center;gap:8px}
.bk h3 svg{width:16px;height:16px;color:var(--accent)}
.bk p{margin:0 0 14px;font-size:12.5px;color:var(--text-2);line-height:1.68}

/* ================= Nudge ================= */
.nudge{
  display:flex;gap:12px;align-items:flex-start;padding:14px 18px;margin-bottom:18px;
  border:1px solid var(--warn-line);background:linear-gradient(180deg,#fffcf4,#fff);
  border-radius:var(--radius);box-shadow:0 1px 2px rgba(150,100,10,.05),0 6px 18px rgba(150,100,10,.07);
}
.nudge svg.i{width:18px;height:18px;color:var(--warn);flex:0 0 18px;margin-top:2px}
.nudge .nt{flex:1;min-width:0;font-size:13px;color:#5f4310;line-height:1.65}
.nudge .nt b{display:block;font-weight:700;color:var(--warn);margin-bottom:2px;font-size:13.5px}
.nudge .na{display:flex;gap:8px;flex-shrink:0;flex-wrap:wrap;align-items:center}

/* ================= Toast / Modal ================= */
.toasts{position:fixed;bottom:24px;right:24px;display:flex;flex-direction:column;gap:10px;z-index:90;align-items:flex-end}
.toast{
  background:linear-gradient(180deg,#12403c,#0b302d);color:#fff;padding:12px 17px;border-radius:11px;
  font-size:13px;font-weight:550;box-shadow:0 12px 34px rgba(8,42,39,.32),inset 0 1px 0 rgba(255,255,255,.09);
  display:flex;align-items:center;gap:9px;animation:tin .28s cubic-bezier(.2,.9,.3,1);max-width:min(90vw,370px);
}
.toast svg{width:15px;height:15px;flex:0 0 15px;color:#5fd6c6}
.toast.err{background:linear-gradient(180deg,#8e2320,#761c19)}
.toast.err svg{color:#ffb3b0}
@keyframes tin{from{opacity:0;transform:translateY(14px) scale(.96)}to{opacity:1;transform:none}}
.mask{position:fixed;inset:0;background:rgba(8,38,36,.42);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px);display:flex;align-items:center;justify-content:center;padding:20px;z-index:100;animation:fin .18s}
@keyframes fin{from{opacity:0}to{opacity:1}}
.modal{background:var(--surface);border-radius:16px;max-width:430px;width:100%;padding:24px;box-shadow:var(--sh-4);animation:min .24s cubic-bezier(.2,.9,.3,1)}
@keyframes min{from{opacity:0;transform:translateY(12px) scale(.97)}to{opacity:1;transform:none}}
.modal h3{margin:0 0 9px;font-size:16.5px;font-weight:660;letter-spacing:-.2px}
.modal p{margin:0 0 20px;font-size:13.5px;color:var(--text-2);line-height:1.7}
.modal .ma{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}

/* ================= Mobile ================= */
@media (max-width:860px){
  .app{flex-direction:column}
  .nav{
    position:sticky;top:0;z-index:50;width:100%;height:auto;flex:none;
    border-right:none;border-bottom:1px solid var(--line);padding:12px 12px 10px;
    flex-direction:column;gap:11px;background:rgba(255,255,255,.96);
    backdrop-filter:saturate(180%) blur(12px);-webkit-backdrop-filter:saturate(180%) blur(12px);
    box-shadow:0 1px 12px rgba(10,50,46,.06);
  }
  .brand{padding:0 2px;border-bottom:none;margin-bottom:0}
  .nav-label,.nav-foot{display:none}
  .nav-scroll{
    display:flex;gap:8px;overflow-x:auto;padding:1px 0 3px;
    -webkit-overflow-scrolling:touch;scrollbar-width:none;
    scroll-snap-type:x proximity;
    mask-image:linear-gradient(90deg,#000 0,#000 calc(100% - 26px),transparent 100%);
    -webkit-mask-image:linear-gradient(90deg,#000 0,#000 calc(100% - 26px),transparent 100%);
  }
  .nav-scroll::-webkit-scrollbar{display:none}
  .nav-item{
    width:auto;flex:0 0 auto;padding:11px 15px;min-height:46px;font-size:13.5px;
    border:1px solid var(--line);background:#fff;scroll-snap-align:start;
  }
  .nav-item.on{border-color:transparent}
  .nav-item.on::before{display:none}
  .main{padding:16px 14px 64px;max-width:100%}
  .hero{min-height:0;margin-bottom:16px}
  .hero-c{padding:20px 16px;max-width:100%;width:100%;min-width:0}
  .hero h1{font-size:20px}
  .hero p{font-size:12.8px;max-width:100%}
  .hero-ov{background:linear-gradient(180deg,rgba(255,255,255,.96) 0%,rgba(255,255,255,.9) 55%,rgba(255,255,255,.72) 100%)}
  .focus-h{flex-wrap:wrap}
  .focus-h .sp{margin-left:0;width:100%;margin-top:8px}
  .focus-h .sp .btn{flex:1}
  .card-h .sp{margin-left:0;width:100%;margin-top:4px}
  .card-h .hint{width:100%;order:9}
  .mini-alert{flex-wrap:wrap}
  .mini-alert .btn{width:100%;margin-top:2px}
  .seg{width:100%}
  .seg button{flex:1;min-height:40px}
  .nudge{flex-wrap:wrap}
  .nudge .na{width:100%}
  .nudge .na .btn{flex:1}
  .topbar h1{font-size:19.5px}
  .topbar-act{width:100%;margin-left:0}
  .topbar-act .btn{flex:1;min-height:46px}
  .card-h,.focus-h{padding:13px 15px}
  .card-b,.focus-b{padding-left:15px;padding-right:15px}
  .card-b.tight{padding:4px 15px 12px}
  .item.od{margin:0 -15px;padding:13px 15px}
  .item::before{left:-15px}
  .btn{min-height:44px;padding:11px 16px}
  .btn-sm{min-height:38px;padding:8px 13px;font-size:12.5px}
  .ico-btn{width:40px;height:40px}
  .ico-btn svg{width:17px;height:17px}
  .chk{width:24px;height:24px;flex:0 0 24px}
  .chk svg{width:14px;height:14px}
  input[type=text],input[type=date],select,textarea{padding:12px;font-size:15px;min-height:46px}
  .f.grow,.form .f{flex:1 1 100%}
  .form .btn{width:100%}
  .notes,.projs{grid-template-columns:1fr}
  .note .del{opacity:1}
  .subbar{padding:10px 15px;gap:6px}
  .sb-l{width:100%;margin-bottom:1px}
  .dgroup .list{padding-left:10px}
  .pt-h .btn{margin-left:0;width:100%;order:9}
  .pt-chk{width:20px;height:20px;flex:0 0 20px}
  .pt-chk svg{width:12px;height:12px}
  .pt-i{padding:7px 0;font-size:13px}
  .toasts{left:14px;right:14px;bottom:14px;align-items:stretch}
  .toast{max-width:100%}
  .frow{flex-wrap:wrap}
  .frow .fa{width:100%;justify-content:flex-start;margin-top:6px}
  .bar-row .bl{flex:0 0 84px;font-size:12px}
  .stat .n{font-size:27px}
  .modal{padding:20px;border-radius:14px}
}
@media (min-width:861px){ .nav-scroll{display:contents} }
@media print{ .nav,.topbar-act,.it-act,.ico-btn,.nudge,.hero-img{display:none} .card,.focus{box-shadow:none;break-inside:avoid} }
